import React from "react";
import { FaSearch, FaFilter } from "react-icons/fa";
import TechnicianItem from "./TechnicianItemComponent";
import FilterSheet from "./FilterSheetComponent";
import AuthCheck from "./AuthCheckComponent";
import Loader from "./LoaderComponent";

const API_URL = "https://iranaserviceapp.ir/test/api";

class TechniciansPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      userList: [],
      displayedUsers: [],
      searchTerm: "",
      isFilterOpen: false,
      filterProvince: "",
      filterCity: "",
      filterSpecialty: "",
      loading: true,
      actionLoading: false,
      authenticated: false,
    };

    this.handleSearchChange = this.handleSearchChange.bind(this);
    this.openFilter = this.openFilter.bind(this);
    this.closeFilter = this.closeFilter.bind(this);
    this.applyFilter = this.applyFilter.bind(this);
    this.handleDelete = this.handleDelete.bind(this);
    this.handleToggleStatus = this.handleToggleStatus.bind(this);
    this.handleDetails = this.handleDetails.bind(this);
  }

  componentDidMount() {
    if (!AuthCheck()) {
      return;
    }

    this.setState(
      {
        authenticated: true,
      },
      () => {
        this.getUsers();
      }
    );
  }

  // =====================================================
  // دریافت کاربران
  // =====================================================

  getUsers = () => {
    const token = localStorage.getItem("token");

    fetch(`${API_URL}/users`, {
      method: "GET",
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
    })
      .then((response) => response.json())
      .then((data) => {
        console.log("USERS API:", data);

        if (String(data.status) !== "1") {
          this.setState({
            userList: [],
            displayedUsers: [],
            loading: false,
          });

          return;
        }

        const users = Array.isArray(data.user)
          ? data.user
          : [];

        console.log("USER LIST:", users);

        this.setState({
          userList: users,
          displayedUsers: users,
          loading: false,
        });
      })
      .catch((error) => {
        console.error("GET USERS ERROR:", error);

        this.setState({
          userList: [],
          displayedUsers: [],
          loading: false,
        });
      });
  };

  // =====================================================
  // سرچ
  // =====================================================

  handleSearchChange(e) {
    const value = e.target.value;

    this.setState(
      {
        searchTerm: value,
      },
      () => {
        this.applyAllFilters();
      }
    );
  }

  // =====================================================
  // باز کردن فیلتر
  // =====================================================

  openFilter() {
    this.setState({
      isFilterOpen: true,
    });
  }

  // =====================================================
  // بستن فیلتر
  // =====================================================

  closeFilter() {
    this.setState({
      isFilterOpen: false,
    });
  }

  // =====================================================
  // اعمال فیلتر
  // =====================================================

  applyFilter() {
    this.applyAllFilters();

    this.setState({
      isFilterOpen: false,
    });
  }

  // =====================================================
  // تبدیل specials به آرایه
  // =====================================================

  getUserSpecials(user) {
    if (!user || !user.specials) {
      return [];
    }

    if (Array.isArray(user.specials)) {
      return user.specials;
    }

    if (typeof user.specials === "string") {
      try {
        const parsed = JSON.parse(user.specials);

        if (Array.isArray(parsed)) {
          return parsed;
        }

        return [parsed];
      } catch (error) {
        return [];
      }
    }

    return [];
  }

  // =====================================================
  // بررسی تخصص کاربر
  // =====================================================

  userHasSpecialty(user, specialty) {
    if (!specialty) {
      return true;
    }

    const specials = this.getUserSpecials(user);

    return specials.some((item) => {
      if (item === null || item === undefined) {
        return false;
      }

      // اگر specials آرایه‌ای از ID باشد
      if (
        typeof item === "string" ||
        typeof item === "number"
      ) {
        return String(item) === String(specialty);
      }

      // اگر specials آرایه‌ای از object باشد
      if (typeof item === "object") {
        return (
          String(item.id) === String(specialty) ||
          String(item.special_id) === String(specialty) ||
          String(item.value) === String(specialty)
        );
      }

      return false;
    });
  }

  // =====================================================
  // اعمال تمام فیلترها + سرچ
  // =====================================================

  applyAllFilters = () => {
    const {
      userList,
      searchTerm,
      filterProvince,
      filterCity,
      filterSpecialty,
    } = this.state;

    const search = searchTerm
      .trim()
      .toLowerCase();

    const result = userList.filter((user) => {
      // =========================================
      // سرچ نام و نام خانوادگی
      // =========================================

      if (search) {
        const name = user.name
          ? String(user.name).toLowerCase()
          : "";

        const family = user.family
          ? String(user.family).toLowerCase()
          : "";

        const fullName =
          `${name} ${family}`.trim();

        if (!fullName.includes(search)) {
          return false;
        }
      }

      // =========================================
      // فیلتر استان
      // =========================================

      if (filterProvince) {
        if (
          String(user.state) !==
          String(filterProvince)
        ) {
          return false;
        }
      }

      // =========================================
      // فیلتر شهر
      // =========================================

      if (filterCity) {
        if (
          String(user.city) !==
          String(filterCity)
        ) {
          return false;
        }
      }

      // =========================================
      // فیلتر تخصص
      // =========================================

      if (filterSpecialty) {
        if (
          !this.userHasSpecialty(
            user,
            filterSpecialty
          )
        ) {
          return false;
        }
      }

      return true;
    });

    this.setState({
      displayedUsers: result,
    });
  };

  // =====================================================
  // حذف کاربر
  // POST /delete
  // =====================================================

  handleDelete(id) {
    const token = localStorage.getItem("token");

    this.setState({
      actionLoading: true,
    });

    fetch(`${API_URL}/delete`, {
      method: "POST",

      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },

      body: JSON.stringify({
        id: id,
      }),
    })
      .then((response) => response.json())
      .then((data) => {
        console.log("DELETE USER:", data);

        if (String(data.status) === "1") {
          this.setState(
            (prevState) => {
              const newUserList =
                prevState.userList.filter(
                  (user) => user.id !== id
                );

              return {
                userList: newUserList,
                actionLoading: false,
              };
            },
            () => {
              this.applyAllFilters();
            }
          );
        } else {
          this.setState({
            actionLoading: false,
          });
        }
      })
      .catch((error) => {
        console.error(
          "DELETE USER ERROR:",
          error
        );

        this.setState({
          actionLoading: false,
        });
      });
  }

  // =====================================================
  // تغییر وضعیت کاربر
  // POST /active
  // =====================================================

  handleToggleStatus(id) {
    const token = localStorage.getItem("token");

    this.setState({
      actionLoading: true,
    });

    fetch(`${API_URL}/active`, {
      method: "POST",

      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },

      body: JSON.stringify({
        id: id,
      }),
    })
      .then((response) => response.json())
      .then((data) => {
        console.log("ACTIVE USER:", data);

        if (String(data.status) === "1") {
          this.getUsersWithActionLoader();
        } else {
          this.setState({
            actionLoading: false,
          });
        }
      })
      .catch((error) => {
        console.error(
          "ACTIVE USER ERROR:",
          error
        );

        this.setState({
          actionLoading: false,
        });
      });
  }

  // =====================================================
  // دریافت کاربران بعد از تغییر وضعیت
  // =====================================================

  getUsersWithActionLoader = () => {
    const token = localStorage.getItem("token");

    fetch(`${API_URL}/users`, {
      method: "GET",

      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
    })
      .then((response) => response.json())
      .then((data) => {
        console.log(
          "USERS API AFTER ACTION:",
          data
        );

        if (String(data.status) !== "1") {
          this.setState({
            userList: [],
            displayedUsers: [],
            loading: false,
            actionLoading: false,
          });

          return;
        }

        const users = Array.isArray(data.user)
          ? data.user
          : [];

        this.setState(
          {
            userList: users,
            loading: false,
            actionLoading: false,
          },
          () => {
            this.applyAllFilters();
          }
        );
      })
      .catch((error) => {
        console.error(
          "GET USERS AFTER ACTION ERROR:",
          error
        );

        this.setState({
          userList: [],
          displayedUsers: [],
          loading: false,
          actionLoading: false,
        });
      });
  };

  // =====================================================
  // جزئیات تعمیرکار
  // =====================================================

  handleDetails(id) {
    console.log("جزئیات تعمیرکار:", id);
  }

  // =====================================================
  // Render
  // =====================================================

  render() {
    const {
      authenticated,
      loading,
      actionLoading,
      displayedUsers,
      searchTerm,
      isFilterOpen,
      filterProvince,
      filterCity,
      filterSpecialty,
    } = this.state;

    if (!authenticated) {
      return null;
    }

    if (loading) {
      return <Loader />;
    }

    return (
      <div dir="rtl">

        {/* =========================================
            لودر عملیات
        ========================================= */}

        {actionLoading && <Loader />}

        {/* =========================================
            بخش Sticky سرچ و فیلتر
        ========================================= */}

        <div
          style={{
            position: "sticky",
            top: 0,
            zIndex: 1000,
            paddingBottom: "4px",

          }}
        >

          <div className="container px-3 pt-4 bg-light">

            {/* =========================================
                سرچ
            ========================================= */}

            <div
              className="d-flex align-items-center gap-2 border rounded-pill px-3 py-2 mb-3 bg-white"
            >

              <input
                type="text"
                placeholder="جستجو..."
                value={searchTerm}
                onChange={this.handleSearchChange}
                className="form-control border-0 shadow-none text-end p-0"
                disabled={actionLoading}
              />

              <FaSearch
                className="text-secondary"
                size={16}
              />

            </div>

            {/* =========================================
                فیلتر
            ========================================= */}

            <div className="d-flex justify-content-end mb-3">

              <button
                type="button"
                onClick={this.openFilter}
                className="btn btn-light border rounded-pill d-flex align-items-center gap-2 px-3 py-2"
                disabled={actionLoading}
              >

                <span>
                  فیلتر
                </span>

                <FaFilter
                  className="text-secondary"
                  size={14}
                />

              </button>

            </div>

            {/* =========================================
                عنوان
            ========================================= */}

            <div className="bg-gra text-center rounded-3 py-3 mb-1">

              <span className="text-primary fw-semibold">
                تعمیرکاران
              </span>

            </div>

          </div>

        </div>

        {/* =========================================
            لیست کاربران
        ========================================= */}

        <div className="container px-3">

          {displayedUsers.map((user) => (
            <TechnicianItem
              key={user.id}
              technician={user}
              onDelete={this.handleDelete}
              onToggleStatus={
                this.handleToggleStatus
              }
              onDetails={this.handleDetails}
            />
          ))}

          {displayedUsers.length === 0 && (
            <div className="text-center text-muted py-5">
              موردی یافت نشد
            </div>
          )}

        </div>

        {/* =========================================
            FilterSheet
        ========================================= */}

        <FilterSheet
          isOpen={isFilterOpen}
          onClose={this.closeFilter}
          onApply={this.applyFilter}

          province={filterProvince}
          city={filterCity}
          specialty={filterSpecialty}

          onProvinceChange={(e) =>
            this.setState({
              filterProvince: e.target.value,
              filterCity: "",
            })
          }

          onCityChange={(e) =>
            this.setState({
              filterCity: e.target.value,
            })
          }

          onSpecialtyChange={(e) =>
            this.setState({
              filterSpecialty: e.target.value,
            })
          }
        />

      </div>
    );
  }
}

export default TechniciansPage;
